import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export const getGeminiResponse = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = "gemini-3-flash-preview";

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        systemInstruction: "You are a professional Petroleum Software Expert Assistant. You provide detailed technical advice on software like Petrel, Eclipse, Landmark, Paradigm, and other oil and gas industry tools. Be concise, technical, and accurate. Use markdown for formatting.",
        temperature: 0.7,
        thinkingConfig: { thinkingBudget: 0 }
      },
    });

    return response.text || "I'm sorry, I couldn't process that technical request. Please try again.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error: Unable to connect to the knowledge engine.";
  }
};

