import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, Sparkles, Terminal } from 'lucide-react';
import { getGeminiResponse } from '../services/gemini';
import { Message } from '../types';

const AIAssistant: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: '您好！我是您的 PetroHub AI 技术助手。我熟悉 Petrel, Eclipse, Landmark, HYSYS 等石油专业软件的操作规程和常见故障处理。请问有什么可以帮您？' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const response = await getGeminiResponse(input);
    const modelMsg: Message = { role: 'model', text: response };

    setMessages(prev => [...prev, modelMsg]);
    setIsLoading(false);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-orange-500 rounded-lg">
            <Terminal className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="font-bold">AI 技术专家</h2>
            <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold">由 Gemini 3 模型驱动</p>
          </div>
        </div>
        <div className="flex items-center gap-2 text-xs bg-slate-800 px-3 py-1.5 rounded-full text-slate-300">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
          模型在线
        </div>
      </div>

      {/* Messages */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex gap-3 max-w-[80%] ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                msg.role === 'user' ? 'bg-orange-500' : 'bg-slate-900'
              }`}>
                {msg.role === 'user' ? <User className="w-4 h-4 text-white" /> : <Bot className="w-4 h-4 text-white" />}
              </div>
              <div className={`p-4 rounded-2xl shadow-sm text-sm ${
                msg.role === 'user' 
                  ? 'bg-orange-500 text-white rounded-tr-none' 
                  : 'bg-white text-slate-700 rounded-tl-none border border-slate-200'
              }`}>
                <div className="prose prose-sm max-w-none leading-relaxed">
                  {msg.text.split('\n').map((line, i) => (
                    <p key={i} className="mb-1">{line}</p>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="flex gap-3 items-center">
              <div className="w-8 h-8 rounded-full bg-slate-900 flex items-center justify-center">
                <Loader2 className="w-4 h-4 text-white animate-spin" />
              </div>
              <div className="bg-white px-4 py-2 rounded-xl text-slate-400 text-xs font-medium italic border border-slate-200">
                专家正在分析技术问题...
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 bg-white border-t">
        <div className="max-w-4xl mx-auto flex items-center gap-2">
          <div className="relative flex-1">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="描述您的软件技术难题，例如: 'Petrel 如何导入自定义断层数据？'"
              className="w-full px-4 py-3 bg-slate-100 border-none rounded-xl focus:ring-2 focus:ring-orange-500 outline-none text-sm transition-all pr-12"
            />
            <div className="absolute right-4 top-1/2 -translate-y-1/2">
              <Sparkles className="w-4 h-4 text-orange-500" />
            </div>
          </div>
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`p-3 rounded-xl transition-all ${
              !input.trim() || isLoading 
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed' 
                : 'bg-orange-500 text-white hover:bg-orange-600 shadow-lg shadow-orange-500/20'
            }`}
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
        <p className="text-[10px] text-center text-slate-400 mt-2">
          提示：您可以询问具体的工作流、脚本语法或软件报错解决方法。
        </p>
      </div>
    </div>
  );
};

export default AIAssistant;

import { GoogleGenAI } from "@google/genai";

// Fix: obtain API key exclusively from process.env.API_KEY and initialize inside the function
export const getGeminiResponse = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  try {
    // Fix: Using correct GenerateContentParameters and ensuring thinkingBudget is set with Gemini 3
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        systemInstruction: "You are a professional Petroleum Software Expert Assistant. You provide detailed technical advice on software like Petrel, Eclipse, Landmark, Paradigm, and other oil and gas industry tools. Be concise, technical, and accurate. Use markdown for formatting.",
        temperature: 0.7,
        thinkingConfig: { thinkingBudget: 0 }
      },
    });

    // Fix: Accessing .text property directly (not a method) as per guidelines
    return response.text || "I'm sorry, I couldn't process that technical request. Please try again.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error: Unable to connect to the knowledge engine.";
  }
};

