import CollaborationSpace from './components/CollaborationSpace';
import AIAssistant from './components/AIAssistant';
import { AppSection, ThemeConfig, UserRole } from './types';

export const ThemeContext = createContext<{
  config: ThemeConfig;
  updateConfig: (updates: Partial<ThemeConfig>) => void;
}>({
  config: {
    primaryColor: '#f97316',
    borderRadius: '3xl',
    showPoints: true,
    compactMode: false,
    siteName: 'PetroHub',
    activeRole: 'USER',
    layoutDensity: 'relaxed'
  },
  updateConfig: () => {}
});

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<AppSection>(AppSection.Plaza);
  const [config, setConfig] = useState<ThemeConfig>({
    primaryColor: '#f97316',
    borderRadius: '3xl',
    showPoints: true,
    compactMode: false,
    siteName: 'PetroHub',
    activeRole: 'USER',
    layoutDensity: 'relaxed'
  });

  const updateConfig = (updates: Partial<ThemeConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const renderContent = () => {
    // 权限检查逻辑
    if (activeSection === AppSection.AdminMgmt && config.activeRole !== 'ADMIN') {
      setActiveSection(AppSection.Plaza);
      return <DiscoveryPlaza />;
    }

    switch (activeSection) {
      case AppSection.Plaza:
        return <DiscoveryPlaza />;
      case AppSection.Collab:
        return <CollaborationSpace />;
      case AppSection.Catalog:
        return <SoftwareCatalog />;
      case AppSection.AI:
        return <AIAssistant />;
      case AppSection.AdminMgmt:
        return (
          <div className="space-y-6 animate-in zoom-in-95 duration-500">
            <h1 className="text-2xl font-black text-slate-800">全站管理后台</h1>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
               <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-sm">
                  <p className="text-xs font-black text-slate-400 uppercase">待审核成果</p>
                  <p className="text-3xl font-black text-orange-500 mt-2">12 件</p>
               </div>
               <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-sm">
                  <p className="text-xs font-black text-slate-400 uppercase">异常上报</p>
                  <p className="text-3xl font-black text-red-500 mt-2">2 条</p>
               </div>
               <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-sm">
                  <p className="text-xs font-black text-slate-400 uppercase">专家入驻申请</p>
                  <p className="text-3xl font-black text-blue-500 mt-2">5 名</p>
               </div>
            </div>
            <div className="bg-white p-8 rounded-3xl border border-slate-200">
               <h2 className="text-lg font-bold mb-4">最新内容合规审计</h2>
               <div className="space-y-3">
                  {[1,2,3].map(i => (
                    <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <span className="text-sm font-bold text-slate-700">石油软件安装包 Crack.zip (用户上传)</span>
                      <span className="px-3 py-1 bg-red-100 text-red-600 text-[10px] font-black rounded-lg">拦截：违规内容</span>
                    </div>
                  ))}
               </div>
            </div>
          </div>
        );
      case AppSection.Profile:
        return (
          <div className="max-w-4xl mx-auto space-y-8">
             <div className={`bg-white rounded-${config.borderRadius} border border-slate-200 p-10 shadow-sm flex flex-col md:flex-row items-center gap-8`}>
                <img src={`https://picsum.photos/seed/${config.activeRole}/200/200`} className={`w-28 h-28 rounded-${config.borderRadius} border-4 border-white shadow-xl`} />
                <div>
                   <h2 className="text-3xl font-black text-slate-900">{config.activeRole === 'EXPERT' ? '张专家' : config.activeRole === 'ADMIN' ? '系统管理员' : '王建国'}</h2>
                   <p className="text-slate-500 font-bold">{config.activeRole} • 数字化工程师</p>
                </div>
             </div>
          </div>
        );
      default:
        return <DiscoveryPlaza />;
    }
  };

  return (
    <ThemeContext.Provider value={{ config, updateConfig }}>
      <Layout activeSection={activeSection} setActiveSection={setActiveSection}>
        {renderContent()}
      </Layout>
    </ThemeContext.Provider>
  );
};

