import AIAssistant from './components/AIAssistant';
import { AppSection, ThemeConfig, UserRole } from './types';

export const ThemeContext = createContext<{
  config: ThemeConfig;
  updateConfig: (updates: Partial<ThemeConfig>) => void;
}>({
  config: {
    primaryColor: '#f97316',
    borderRadius: '3xl',
    showPoints: true,
    compactMode: false,
    siteName: 'PetroHub',
    activeRole: 'USER',
    layoutDensity: 'relaxed',
    isEditMode: false
  },
  updateConfig: () => {}
});

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<AppSection>(AppSection.Plaza);
  const [config, setConfig] = useState<ThemeConfig>({
    primaryColor: '#f97316',
    borderRadius: '3xl',
    showPoints: true,
    compactMode: false,
    siteName: 'PetroHub',
    activeRole: 'USER',
    layoutDensity: 'relaxed',
    isEditMode: false
  });

  const updateConfig = (updates: Partial<ThemeConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const renderContent = () => {
    // 权限与管理逻辑模拟
    if (activeSection === AppSection.AdminMgmt && config.activeRole !== 'ADMIN') {
      setActiveSection(AppSection.Plaza);
      return <DiscoveryPlaza />;
    }

    switch (activeSection) {
      case AppSection.Plaza:
        return <DiscoveryPlaza />;
      case AppSection.Collab:
        return <CollaborationSpace />;
      case AppSection.Catalog:
        return <SoftwareCatalog />;
      case AppSection.AI:
        return <AIAssistant />;
      case AppSection.AdminMgmt:
        return (
          <div className="space-y-6 animate-in zoom-in-95 duration-500">
            <h1 className="text-3xl font-black text-slate-800">系统审计中心</h1>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
               {[
                 { label: '待审技术成果', val: '12 件', color: 'text-orange-500' },
                 { label: '敏感词拦截', val: '158 次', color: 'text-red-500' },
                 { label: '专家实名申请', val: '5 名', color: 'text-blue-500' },
                 { label: '服务器负载', val: '24%', color: 'text-green-500' },
               ].map((stat, i) => (
                 <div key={i} className="bg-white p-6 rounded-3xl border border-slate-200">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
                    <p className={`text-2xl font-black mt-2 ${stat.color}`}>{stat.val}</p>
                 </div>
               ))}
            </div>
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200">
               <h2 className="text-lg font-bold mb-6">内容安全日志</h2>
               <div className="space-y-3">
                  {[
                    { msg: '用户 "Explo_New" 上传了包含 Crack 敏感词的文件', time: '10 分钟前', status: '已自动删除' },
                    { msg: '专家 "张博士" 发布了新的行业标准工作流', time: '1 小时前', status: '待审核' },
                    { msg: '系统检测到异常登录活动（来自未知 IP）', time: '3 小时前', status: '已拦截' },
                  ].map((log, i) => (
                    <div key={i} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <div className="flex items-center gap-3">
                        <ShieldAlert className="w-4 h-4 text-slate-400" />
                        <span className="text-sm font-bold text-slate-700">{log.msg}</span>
                      </div>
                      <div className="flex items-center gap-4">
                        <span className="text-[10px] text-slate-400 font-bold">{log.time}</span>
                        <span className={`px-3 py-1 text-[10px] font-black rounded-lg ${log.status === '待审核' ? 'bg-orange-100 text-orange-600' : 'bg-slate-200 text-slate-500'}`}>{log.status}</span>
                      </div>
                    </div>
                  ))}
               </div>
            </div>
          </div>
        );
      case AppSection.Profile:
        return (
          <div className="max-w-4xl mx-auto space-y-8 animate-in slide-in-from-bottom-4 duration-700">
             <div className="bg-white rounded-[3rem] border border-slate-200 p-12 shadow-sm flex flex-col md:flex-row items-center gap-12 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-slate-50 rounded-full translate-x-1/2 -translate-y-1/2"></div>
                <div className="relative">
                  <img src={`https://picsum.photos/seed/${config.activeRole}/200/200`} className="w-40 h-40 rounded-[2.5rem] border-8 border-white shadow-2xl rotate-3" />
                  <div className="absolute -bottom-2 -right-2 bg-orange-500 text-white text-[10px] font-black px-4 py-1.5 rounded-full shadow-lg">PRO</div>
                </div>
                <div className="relative z-10 text-center md:text-left">
                   <h2 className="text-4xl font-black text-slate-900 mb-2">{config.activeRole === 'ADMIN' ? '王主管' : config.activeRole === 'EXPERT' ? '张专家' : '李工程师'}</h2>
                   <p className="text-slate-500 font-bold mb-6">数字化转型办公室 • 技术负责人</p>
                   <div className="flex flex-wrap gap-3 justify-center md:justify-start">
                      {['OSDU', 'Python井斜', '地质力学'].map(tag => (
                        <span key={tag} className="px-4 py-2 bg-slate-100 rounded-xl text-xs font-bold text-slate-500">{tag}</span>
                      ))}
                   </div>
                </div>
             </div>
          </div>
        );
      default:
        return <DiscoveryPlaza />;
    }
  };

  return (
    <ThemeContext.Provider value={{ config, updateConfig }}>
      <Layout activeSection={activeSection} setActiveSection={setActiveSection}>
        {renderContent()}
      </Layout>
    </ThemeContext.Provider>
  );
};

