                    </p>
                 </div>
              </div>

              <div className="lg:col-span-3 space-y-6">
                 <div className="flex items-center justify-between">
                    <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">最新分享</h3>
                    <div className="flex items-center gap-2">
                       {['全部', '文档', '课件', '视频'].map(f => (
                         <button key={f} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase transition-all ${f === '全部' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                       ))}
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {workshopItems.map(item => <KnowledgeCard key={item.id} item={item} mode="workshop" />)}
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

