                           <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                              <div className={`flex gap-3 max-w-[80%] ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
                                 <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${m.role === 'user' ? 'bg-blue-600 text-white' : m.role === 'model' ? 'bg-slate-800 text-white' : 'bg-orange-500 text-white'}`}>
                                    {m.role === 'user' ? <User className="w-4 h-4" /> : m.role === 'model' ? <ShieldCheck className="w-4 h-4" /> : <Headphones className="w-4 h-4" />}
                                 </div>
                                 <div className="space-y-1">
                                    <p className={`text-[9px] font-black text-slate-400 uppercase ${m.role === 'user' ? 'text-right' : ''}`}>{m.senderName}</p>
