                                       {m.text}
                                    </div>
                                 </div>
                              </div>
                           </div>
                        ))}
                     </div>

                     {/* 输入区域 */}
                     <div className="p-6 bg-white border-t border-slate-100">
                        <div className="flex gap-4 items-center max-w-4xl mx-auto">
                           <input 
                              type="text" 
                              value={chatInput}
                              onChange={(e) => setChatInput(e.target.value)}
                              onKeyDown={(e) => e.key === 'Enter' && handleChatSend()}
                              placeholder="在群聊中输入您的问题素材或追问..."
                              className="flex-1 bg-slate-50 border-none rounded-[1.5rem] px-6 py-3 text-xs outline-none focus:ring-2 focus:ring-blue-600/10 h-12"
                           />
                           <button onClick={handleChatSend} className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl active:scale-95 transition-all"><Send className="w-5 h-5" /></button>
                        </div>
                     </div>
                  </div>
               )}
            </div>
          )}

        </div>
      </div>
    </div>
  );
};

