                        className="flex-1 bg-slate-50 border-none rounded-[1.5rem] px-6 py-3 text-xs outline-none focus:ring-2 focus:ring-blue-600/10 min-h-[50px] resize-none"
                     />
                     <button onClick={handleAiSend} className="p-4 bg-blue-600 text-white rounded-2xl shadow-xl shadow-blue-500/20 active:scale-95 transition-all"><Send className="w-5 h-5" /></button>
                  </div>
               </div>
            </div>
          )}

          {/* 主题问答模式 */}
          {mode === 'TOPIC' && (
            <div className="p-8">
               {selectedId ? (
                  <div className="animate-in slide-in-from-right-4 duration-500 space-y-8">
                    <button onClick={() => setSelectedId(null)} className="flex items-center gap-2 text-slate-400 hover:text-slate-800 font-bold mb-4 text-xs">
                       <ArrowLeft className="w-3.5 h-3.5" /> 返回问题列表
                    </button>
                    {/* 详情展示 */}
