                       <div className="flex items-center gap-3 mb-6">
                          {problems.find(p => p.id === selectedId)?.tags.includes('AI自动生成') && (
                            <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-[9px] font-black border border-blue-100 flex items-center gap-1">
                               <Sparkles className="w-3 h-3" /> AI 资产转换
                            </span>
                          )}
