                            <span className="px-3 py-1 bg-amber-50 text-amber-600 rounded-full text-[9px] font-black border border-amber-100 flex items-center gap-1">
                               <Users className="w-3 h-3" /> 专家会诊存档
                            </span>
                          )}
                       </div>
                       <h2 className="text-2xl font-black text-slate-800 mb-6">{problems.find(p => p.id === selectedId)?.title}</h2>
                       <div className="prose prose-sm max-w-none text-slate-600 font-medium leading-relaxed">
                          <div className="p-8 bg-slate-50 rounded-[2rem] border border-slate-100 mb-8">
                             <p className="text-xs font-black text-slate-400 uppercase mb-4">核心诊断内容</p>
                             <p className="mb-4">根据历史问答与实时交流整理，针对该问题的最佳实践方案如下：</p>
                             <ul className="list-disc pl-5 space-y-2">
                                <li>核查数据坐标系统的单位一致性。</li>
                                <li>在 Pillar Gridding 模块中先执行断层几何自交清理。</li>
                                <li>使用 Python 脚本进行批量基准面偏移校正。</li>
                             </ul>
                          </div>
                          <div className="flex items-center gap-4 pt-6 border-t border-slate-50">
                             <button className="flex items-center gap-2 text-[10px] font-black text-slate-400 hover:text-blue-600"><ThumbsUp className="w-4 h-4" /> 对我有帮助</button>
                             <button className="flex items-center gap-2 text-[10px] font-black text-slate-400 hover:text-blue-600"><Share2 className="w-4 h-4" /> 分享案例</button>
                          </div>
                       </div>
                    </div>
                  </div>
               ) : (
                  <div className="space-y-4">
                     <div className="flex items-center justify-between mb-6">
                        <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">
                           {selectedCategory} 话题广场
                        </h3>
                        <div className="flex gap-2">
                           <button className="px-4 py-1.5 bg-slate-100 rounded-full text-[10px] font-black text-slate-500 uppercase">最新</button>
                           <button className="px-4 py-1.5 bg-blue-50 rounded-full text-[10px] font-black text-blue-600 uppercase">高悬赏</button>
                        </div>
                     </div>
                     {filteredProblems.map(p => (
                        <div key={p.id} onClick={() => setSelectedId(p.id)} className={`bg-white p-6 rounded-[2rem] border transition-all cursor-pointer group flex gap-6 items-center ${p.tags.includes('AI自动生成') || p.tags.includes('会诊结论') ? 'border-amber-100 bg-amber-50/10 shadow-sm' : 'border-slate-200 hover:border-blue-500 hover:shadow-xl'}`}>
                           <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${p.status === 'resolved' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                              {p.tags.includes('AI自动生成') ? <BookMarked className="w-6 h-6 text-blue-500" /> : p.tags.includes('会诊结论') ? <ClipboardCheck className="w-6 h-6 text-amber-500" /> : (p.status === 'resolved' ? <CheckCircle2 className="w-6 h-6" /> : <AlertCircle className="w-6 h-6" />)}
                           </div>
                           <div className="flex-1 min-w-0">
                              <h3 className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors truncate mb-1">{p.title}</h3>
                              <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 uppercase tracking-tight">
                                 <span className="bg-slate-50 px-2 py-0.5 rounded border">{p.software}</span>
                                 <span>• {p.author}</span>
                                 <span>• {p.time}</span>
                              </div>
                           </div>
                           <div className="text-center px-4 py-2 bg-slate-50 rounded-xl">
                              <p className="text-xs font-black text-slate-800">{p.replies}</p>
                              <p className="text-[8px] font-bold text-slate-400 uppercase">回复</p>
                           </div>
                        </div>
                     ))}
                  </div>
               )}
            </div>
          )}

          {/* 即时群聊模式 */}
          {mode === 'INSTANT' && (
            <div className="h-full">
               {!isGroupChatActive ? (
                  <div className="p-10 flex flex-col items-center justify-center h-full space-y-10 animate-in zoom-in-95 duration-500">
                     <div className="text-center space-y-4 max-w-lg">
                        <div className="w-20 h-20 bg-blue-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
                           <Headphones className="w-10 h-10 text-blue-600" />
                        </div>
                        <h2 className="text-2xl font-black text-slate-800 tracking-tight">即时多方会诊</h2>
                        <p className="text-sm text-slate-500 font-medium leading-relaxed">
                           根据您关注的 <span className="text-blue-600 font-black">{selectedCategory}</span> 领域，
                           系统已为您锁定以下在线专家。请勾选并开启实时技术支援。
                        </p>
                     </div>

                     <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-2xl">
                        {mockExperts.filter(e => selectedCategory === '全部' || e.specialties.some(s => s.includes(selectedCategory))).map(expert => (
                           <div 
                              key={expert.id} 
                              onClick={() => {
                                 setSelectedExperts(prev => prev.includes(expert.id) ? prev.filter(id => id !== expert.id) : [...prev, expert.id])
                              }}
                              className={`p-6 rounded-[2rem] border transition-all cursor-pointer relative group ${selectedExperts.includes(expert.id) ? 'border-blue-600 bg-blue-50/50 ring-2 ring-blue-500/10' : 'bg-white border-slate-200 hover:border-blue-300'}`}
                           >
                              <div className="flex items-center gap-4">
                                 <img src={expert.avatar} className="w-12 h-12 rounded-full border-2 border-white shadow-sm" />
                                 <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2">
                                       <p className="text-sm font-black text-slate-800">{expert.name}</p>
                                       <span className="text-[8px] font-black text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded uppercase">LV.{expert.lv}</span>
                                    </div>
                                    <p className="text-[10px] text-slate-400 font-bold truncate">擅长：{expert.specialties.join('、')}</p>
                                 </div>
                                 <div className={`w-2.5 h-2.5 rounded-full ${expert.status === 'online' ? 'bg-green-500' : 'bg-orange-400'}`}></div>
                              </div>
                              {selectedExperts.includes(expert.id) && (
                                <div className="absolute top-4 right-4 bg-blue-600 rounded-full p-1"><CheckCircle2 className="w-3 h-3 text-white" /></div>
                              )}
                           </div>
                        ))}
                     </div>

                     <button 
                        onClick={handleStartInstant}
                        disabled={selectedExperts.length === 0}
                        className={`px-12 py-4 rounded-2xl font-black text-sm shadow-xl transition-all active:scale-95 flex items-center gap-3 ${selectedExperts.length > 0 ? 'bg-slate-900 text-white shadow-slate-900/20' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                     >
                        开启即时研讨 <Zap className="w-4 h-4 fill-yellow-400 text-yellow-400" />
                     </button>
                  </div>
               ) : (
                  <div className="h-full flex flex-col animate-in slide-in-from-bottom-4 duration-500">
                     {/* 群聊头部 */}
                     <div className="p-4 bg-slate-900 text-white flex items-center justify-between">
                        <div className="flex items-center gap-4">
                           <button onClick={() => setIsGroupChatActive(false)} className="p-2 hover:bg-white/10 rounded-lg"><ArrowLeft className="w-4 h-4" /></button>
                           <div>
                              <h3 className="text-xs font-black">技术会诊室：{selectedCategory} 问题诊断</h3>
                              <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{selectedExperts.length} 位专家已就位</p>
                           </div>
                        </div>
                        <div className="flex items-center gap-4">
                           <button 
                              onClick={() => handleConvertToTopic('INSTANT')}
                              className="px-4 py-1.5 bg-blue-600 hover:bg-blue-500 rounded-full text-[10px] font-black flex items-center gap-2 transition-all"
                           >
                              <ClipboardCheck className="w-3 h-3" /> 生成会诊报告并沉淀
                           </button>
                           <div className="flex -space-x-2">
                              {selectedExperts.map(id => {
                                 const exp = mockExperts.find(e => e.id === id);
                                 return <img key={id} src={exp?.avatar} className="w-6 h-6 rounded-full border-2 border-slate-900" title={exp?.name} />
                              })}
                           </div>
                        </div>
                     </div>

                     <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50">
                        {chatMessages.map((m, i) => (
                           <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                              <div className={`flex gap-3 max-w-[80%] ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
                                 <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 ${m.role === 'user' ? 'bg-blue-600 text-white' : m.role === 'model' ? 'bg-slate-800 text-white' : 'bg-orange-500 text-white'}`}>
                                    {m.role === 'user' ? <User className="w-4 h-4" /> : m.role === 'model' ? <ShieldCheck className="w-4 h-4" /> : <Headphones className="w-4 h-4" />}
                                 </div>
                                 <div className="space-y-1">
                                    <p className={`text-[9px] font-black text-slate-400 uppercase ${m.role === 'user' ? 'text-right' : ''}`}>{m.senderName}</p>
                                    <div className={`p-4 rounded-[1.5rem] text-xs font-medium leading-relaxed shadow-sm ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-slate-100 rounded-tl-none text-slate-700'}`}>
                                       {m.text}
                                    </div>
                                 </div>
                              </div>
                           </div>
                        ))}
                     </div>

                     <div className="p-6 bg-white border-t border-slate-100">
                        <div className="flex gap-4 items-center max-w-4xl mx-auto">
                           <input 
                              type="text" 
                              value={chatInput}
                              onChange={(e) => setChatInput(e.target.value)}
                              onKeyDown={(e) => e.key === 'Enter' && handleChatSend()}
                              placeholder="在群聊中输入您的问题素材或追问..."
                              className="flex-1 bg-slate-50 border-none rounded-[1.5rem] px-6 py-3 text-xs outline-none focus:ring-2 focus:ring-blue-600/10 h-12"
                           />
                           <button onClick={handleChatSend} className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl active:scale-95 transition-all"><Send className="w-5 h-5" /></button>
                        </div>
                     </div>
                  </div>
               )}
            </div>
          )}

        </div>
      </div>
    </div>
  );
};

export default ProblemSpace;

export type UserRole = 'ADMIN' | 'EXPERT' | 'USER' | 'LIBRARIAN';

