import React, { useState, useContext, useMemo, useEffect } from 'react';
import { 
  Search, Filter, User, ArrowLeft, Send, Heart,
  MessagesSquare, Info, Users, AlertCircle, CheckCircle2,
  Sparkles, MessageCircle, MoreVertical, Plus, Bot,
  Zap, MessageSquareText, Headphones, X, ShieldCheck, ChevronRight,
  BookMarked, Share2, ClipboardCheck, LayoutGrid, Map, Waves, Hammer, Repeat,
  ThumbsUp, Tags, Layers, Monitor, HardDrive, Cpu, Settings
} from 'lucide-react';
import { ThemeContext } from '../App';
import { getGeminiResponse } from '../services/gemini';
import { ProblemItem, ProblemMode, Expert, Message } from '../types';

const ProblemSpace: React.FC = () => {
  const { config } = useContext(ThemeContext);
  const [mode, setMode] = useState<ProblemMode>('TOPIC');

  // 复合筛选状态
  const [selectedDomain, setSelectedDomain] = useState<string>('全部');
  const [selectedSoftware, setSelectedSoftware] = useState<string>('全部');
  const [selectedType, setSelectedType] = useState<string>('全部');

  const [selectedId, setSelectedId] = useState<string | null>(null);

  // 扩展后的问题列表
  const [problems, setProblems] = useState<ProblemItem[]>([
    { id: 'p1', title: 'Petrel 2024 断块区 Pillar Gridding 报错 0x89', software: 'Petrel', category: '地学建模', businessDomain: '勘探', problemType: '技术', status: 'resolved', author: '李工', time: '10分钟前', replies: 4, aiScore: 95, tags: ['Pillar', '报错'] },
    { id: 'p2', title: 'Eclipse 如何在数值模拟中准确描述复杂断块的传导率？', software: 'Eclipse', category: '数值模拟', businessDomain: '开发', problemType: '业务', status: 'open', author: '王研究员', time: '1小时前', replies: 0, aiScore: 82, tags: ['传导率', '断块'] },
    { id: 'p3', title: '【求教】DecisionSpace 导入地震数据时基准面不对齐', software: 'Landmark', category: '地震解释', businessDomain: '勘探', problemType: '操作', status: 'open', author: 'Sarah', time: '5小时前', replies: 12, aiScore: 78, tags: ['导入', '基准面'] },
    { id: 'p4', title: 'OSDU 数据平台接口认证失败 403 错误', software: 'OSDU', category: '数据管理', businessDomain: '数字化', problemType: '系统', status: 'open', author: '运维小周', time: '2小时前', replies: 3, aiScore: 90, tags: ['API', '权限'] },
    { id: 'p5', title: 'HYSYS 动态模拟课件下载及实验参数对照', software: 'HYSYS', category: '流程模拟', businessDomain: '炼化', problemType: '课件', status: 'resolved', author: '张教授', time: '昨天', replies: 45, aiScore: 88, tags: ['课件', '教学'] },
  ]);

  // 维度定义
  const businessDomains = [
    { name: '全部', icon: LayoutGrid },
    { name: '勘探', icon: Map },
    { name: '开发', icon: Zap },
    { name: '钻完井', icon: Hammer },
    { name: '集输', icon: Repeat },
    { name: '炼化', icon: Cpu },
    { name: '数字化', icon: Monitor }
  ];

  const softwares = ['全部', 'Petrel', 'Eclipse', 'Landmark', 'HYSYS', 'OSDU', '其他'];
  const problemTypes = ['全部', '技术', '业务', '操作', '数据', '系统', '课件', '其他'];

  // 复合过滤逻辑
  const filteredProblems = useMemo(() => {
    return problems.filter(p => {
      const matchDomain = selectedDomain === '全部' || p.businessDomain === selectedDomain;
      const matchSoftware = selectedSoftware === '全部' || p.software === selectedSoftware;
      const matchType = selectedType === '全部' || p.problemType === selectedType;
      return matchDomain && matchSoftware && matchType;
    });
  }, [problems, selectedDomain, selectedSoftware, selectedType]);

  // AI 模式状态
  const [aiInput, setAiInput] = useState('');
  const [aiMessages, setAiMessages] = useState<Message[]>([
    { role: 'model', text: '您好，我是 AI 专家助手。请描述您的技术问题，我将为您调取全球库中的相似案例。' }
  ]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // 即时问答模式状态
  const [selectedExperts, setSelectedExperts] = useState<string[]>([]);
  const [isGroupChatActive, setIsGroupChatActive] = useState(false);
  const [chatInput, setChatInput] = useState('');
  const [chatMessages, setChatMessages] = useState<Message[]>([
    { role: 'model', text: '系统：已为您邀请所选专家加入会诊群聊。专家可能需要 1-2 分钟查看您的提问素材。', senderName: '系统通知' }
  ]);

  const [isConverting, setIsConverting] = useState(false);

  const handleConvertToTopic = async (source: 'AI' | 'INSTANT') => {
    setIsConverting(true);
    await new Promise(resolve => setTimeout(resolve, 1500));

    let newTopic: ProblemItem;
    if (source === 'AI') {
      const lastQuestion = aiMessages.filter(m => m.role === 'user').pop()?.text || "AI 辅助解答课题";
      newTopic = {
        id: `p-ai-${Date.now()}`,
        title: `【AI案例】${lastQuestion.substring(0, 35)}...`,
        software: 'AI 综合',
        category: '智能分析',
        businessDomain: selectedDomain === '全部' ? '数字化' : selectedDomain,
        problemType: '技术',
        status: 'resolved',
        author: '我 (由AI转写)',
        time: '刚刚',
        replies: 1,
        aiScore: 100,
        tags: ['AI自动生成', '知识沉淀']
      };
    } else {
      newTopic = {
        id: `p-ins-${Date.now()}`,
        title: `【专家会诊记录】关于${selectedDomain}领域现场问题的多方研讨`,
        software: '多软件协同',
        category: '综合诊断',
        businessDomain: selectedDomain,
        problemType: '业务',
        status: 'resolved',
        author: '会诊秘书',
        time: '刚刚',
        replies: chatMessages.length,
        aiScore: 88,
        tags: ['会诊结论', '实战案例']
      };
    }

    setProblems(prev => [newTopic, ...prev]);
    setIsConverting(false);
    setMode('TOPIC');
    setSelectedId(newTopic.id);
  };

  const handleAiSend = async () => {
    if (!aiInput.trim()) return;
    const userMsg: Message = { role: 'user', text: aiInput };
    setAiMessages(prev => [...prev, userMsg]);
    setAiInput('');
    setIsAiLoading(true);
    const response = await getGeminiResponse(`【技术难题咨询】${aiInput}`);
    setAiMessages(prev => [...prev, { role: 'model', text: response }]);
    setIsAiLoading(false);
  };

  const handleChatSend = () => {
    if (!chatInput.trim()) return;
    setChatMessages(prev => [...prev, { role: 'user', text: chatInput, senderName: '我' }]);
    setChatInput('');
  };

  return (
    <div className="max-w-7xl mx-auto h-[calc(100vh-120px)] flex gap-6 animate-in fade-in duration-700 overflow-hidden relative">

      {isConverting && (
        <div className="absolute inset-0 z-[200] bg-slate-900/40 backdrop-blur-sm flex items-center justify-center">
           <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl flex flex-col items-center gap-4 animate-in zoom-in-95">
              <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center">
                 <BookMarked className="w-8 h-8 text-blue-600 animate-bounce" />
              </div>
              <div className="text-center">
                 <h3 className="text-sm font-black text-slate-800">正在萃取核心知识点...</h3>
                 <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-widest">AI 正在为您生成结构化主题报告</p>
              </div>
           </div>
        </div>
      )}

