                    <div className="w-full bg-white/10 h-1.5 rounded-full overflow-hidden mb-6">
                       <div className="bg-blue-500 h-full w-[35%]"></div>
                    </div>
                    <button className="w-full py-3 bg-blue-600 rounded-xl text-xs font-black">继续我的课程</button>
                 </div>
                 <div className="absolute -right-6 -bottom-6 w-32 h-32 bg-blue-500/10 rounded-full blur-3xl"></div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'library' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
           <div className="lg:col-span-1 space-y-6">
              <div className="bg-white rounded-[2.5rem] border border-slate-200 p-8 shadow-sm">
                 <div className="flex items-center justify-between mb-8">
                    <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                       <FolderTree className="w-4 h-4 text-blue-600" />
                       子馆分类导航
                    </h3>
                    {/* Fix: Wrap icon in a span to apply title attribute instead of passing it to the Lucide icon component */}
                    {isAdmin && (
                      <span className="cursor-pointer" title="管理栏目结构">
                        <Settings2 className="w-4 h-4 text-slate-300 hover:text-red-500" />
                      </span>
                    )}
                 </div>
                 <div className="space-y-6">
                    {categories.map((cat) => (
                      <div key={cat.id} className="space-y-2">
                        <div className="flex items-center justify-between">
                          <p className="text-xs font-black text-slate-800 flex items-center gap-2">
                             <span className="w-1.5 h-1.5 rounded-full bg-blue-600"></span>
                             {cat.name}
                          </p>
                          <span className="text-[8px] font-black text-slate-300 uppercase">馆长: {cat.curator}</span>
                        </div>
                        {cat.children?.map(sub => (
                          <div key={sub.id} className="pl-4 space-y-1">
                             <p className="text-[11px] font-bold text-slate-500 hover:text-blue-600 cursor-pointer transition-colors flex items-center gap-2">
                                <ChevronRight className="w-3 h-3" /> {sub.name}
                             </p>
                             <div className="pl-4 space-y-1">
                                {sub.children?.map(leaf => (
                                   <p key={leaf.id} onClick={() => setSelectedCat(leaf.id)} className={`text-[10px] font-bold py-1 px-3 rounded-lg cursor-pointer transition-all ${selectedCat === leaf.id ? 'bg-blue-50 text-blue-600' : 'text-slate-400 hover:bg-slate-50'}`}>
                                      {leaf.name}
                                   </p>
                                ))}
                             </div>
                          </div>
                        ))}
                      </div>
                    ))}
                    {isAdmin && (
                      <button className="w-full py-2 border border-dashed border-slate-200 rounded-xl text-[10px] font-black text-slate-400 hover:border-red-300 hover:text-red-500 transition-all flex items-center justify-center gap-2">
                         <Plus className="w-3 h-3" /> 新增主栏目
                      </button>
                    )}
                 </div>
              </div>

              {isAdmin && (
                <div className="bg-red-50 rounded-[2rem] p-6 border border-red-100">
                   <h3 className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-4 flex items-center gap-2"><ShieldCheck className="w-4 h-4" /> 管理员面板</h3>
                   <div className="space-y-2">
                      <button className="w-full py-2 bg-white text-red-600 rounded-xl text-[10px] font-black border border-red-100 hover:bg-red-50 transition-all">分配子馆馆长</button>
                      <button className="w-full py-2 bg-white text-red-600 rounded-xl text-[10px] font-black border border-red-100 hover:bg-red-50 transition-all">导入大宗官方文档</button>
                   </div>
                </div>
              )}
           </div>

           <div className="lg:col-span-3 space-y-6">
              <div className="flex items-center gap-4 bg-white p-4 rounded-3xl border border-slate-200">
                 <div className="relative flex-1">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                    <input type="text" placeholder="在官方图书馆搜索..." className="w-full bg-slate-50 border-none pl-12 pr-4 py-3 rounded-2xl text-xs outline-none focus:ring-2 focus:ring-blue-500/10" />
                 </div>
                 <button className="p-3 bg-slate-100 text-slate-500 rounded-2xl hover:bg-slate-200 transition-all"><Filter className="w-4 h-4" /></button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 {libraryItems.length > 0 ? (
                   libraryItems.map(item => <KnowledgeCard key={item.id} item={item} mode="library" />)
                 ) : (
                   <div className="col-span-full py-20 flex flex-col items-center justify-center text-slate-300 space-y-4">
                      <Library className="w-12 h-12 opacity-20" />
                      <p className="text-sm font-bold">该栏目下暂无精选资源</p>
                   </div>
                 )}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'workshop' && (
        <div className="space-y-8">
           <div className="bg-white p-8 rounded-[3rem] border border-slate-200 flex flex-col md:flex-row items-center justify-between gap-6 shadow-sm">
              <div className="flex items-center gap-6">
                 <div className="w-16 h-16 bg-blue-50 rounded-[1.5rem] flex items-center justify-center">
                    <Warehouse className="w-8 h-8 text-blue-600" />
                 </div>
                 <div>
                    <h2 className="text-xl font-black text-slate-800">用户知识坊</h2>
                    <p className="text-sm text-slate-500 font-medium">自由分享、开放交流。优质内容将被馆长收录入图书馆！</p>
                 </div>
              </div>
              <div className="flex gap-3">
                 <button className="px-8 py-3 bg-blue-600 text-white rounded-2xl font-black text-sm flex items-center gap-2 shadow-xl shadow-blue-500/20 active:scale-95 transition-all">
                    <Plus className="w-5 h-5" /> 上传分享
                 </button>
              </div>
           </div>

           <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
              <div className="lg:col-span-1 space-y-6">
                 <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
                    <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center gap-2">
                       <ThumbsUp className="w-4 h-4 text-orange-500" />
                       馆长关注热榜
                    </h3>
                    <div className="space-y-4">
                       {workshopItems.slice(0, 5).map((item, i) => (
                         <div key={item.id} className="flex items-start gap-3 group cursor-pointer">
                            <div className="w-5 h-5 rounded bg-slate-100 flex items-center justify-center text-[10px] font-black text-slate-400 group-hover:bg-orange-500 group-hover:text-white transition-colors">{i+1}</div>
                            <div className="flex-1 min-w-0">
                               <p className="text-[11px] font-bold text-slate-700 truncate group-hover:text-blue-600">{item.title}</p>
                               <div className="flex items-center gap-2 text-[8px] text-slate-400 font-bold uppercase mt-1">
                                  <span>{item.author}</span>
                                  <span>{item.likes} 推荐</span>
                               </div>
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>

                 <div className="bg-blue-50 p-8 rounded-[2.5rem] border border-blue-100">
                    <h3 className="text-xs font-black text-blue-800 uppercase tracking-widest mb-4 flex items-center gap-2">
                       <Info className="w-4 h-4" /> 馆长寄语
                    </h3>
                    <p className="text-[11px] text-blue-600/70 font-bold leading-relaxed">
                       我是地学建模馆馆长张首席。我正在寻找有关“Petrel 自动化建模”的优质案例，点赞超过 50 的相关文档我会亲自审核并收入主馆！
                    </p>
                 </div>
              </div>

              <div className="lg:col-span-3 space-y-6">
                 <div className="flex items-center justify-between">
                    <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">最新分享</h3>
                    <div className="flex items-center gap-2">
                       {['全部', '文档', '课件', '视频'].map(f => (
                         <button key={f} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase transition-all ${f === '全部' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                       ))}
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {workshopItems.map(item => <KnowledgeCard key={item.id} item={item} mode="workshop" />)}
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default LearningPavilion;
